1160:export async function addPeriod(page: Page, f: { name: string; from: string; to: string; cap?: string }): Promise<boolean> {
1161:  const all = page.locator('[data-testid^="period-row-"]');
1163:  await page.getByTestId('period-form-name').fill(f.name);
1164:  await page.getByTestId('period-form-from').fill(f.from);
1165:  await page.getByTestId('period-form-to').fill(f.to);
